+    private static final Set<Character> INVALID_TOKEN_NAME_CHARS = Set.of(
+        '!', '"', '#', '$', '%', '&', '\'', '(', ')', '*', '+', ',', '.', '/', ':', ';', '<', '=', '>', '?', '@', '[',
