+  - key_not_to_replace: { _below_is_target_for_tests: 0 }
+  - key_to_replace: "value_to_replace"
+
+---
+"Also has key_value to replace":
+
+  - do:
+      something:
+        that_is: true
+
+  - do:
+      and: again
+
+  - key_not_to_replace: { hits.total.value: 0 }
+  - key_to_replace: "value_to_replace"
+  - key_not_to_replace: { _below_is_target_for_tests: 0 }
